function assert(x,m){if(!x)throw Error(m);}function sha(b){return crypto.createHash('sha256').update(b).digest('hex');}function fsha(p){return sha(fs.readFileSync(p));}function stable(x){return JSON.stringify(x,null,2)+'\n';}function mismatch(a,b){for(let i=0;i<Math.min(a.length,b.length);i++)if(a[i]!==b[i])return i;return a.length===b.length?null:Math.min(a.length,b.length);}
function verifyPins(){for(const [r,h] of Object.entries(PINS))assert(fsha(path.resolve(HERE,r))===h,'pin '+r);X.R.verifySources();}
function orientIndices(n,name){const all=[...Array(n).keys()],pairs=[];for(let i=0;i<n;i+=2)pairs.push(all.slice(i,i+2));const toks=[all.slice(0,2)];for(let i=2;i<n;i+=5)toks.push(all.slice(i,i+5));if(name==='forward')return all;if(name==='full_hex_reverse')return all.slice().reverse();if(name==='byte_pair_reverse')return pairs.slice().reverse().flat();if(name==='nibble_swap')return pairs.flatMap(x=>x.slice().reverse());if(name==='visible_token_reverse')return toks.slice().reverse().flat();throw Error(name);}
function inverseOrient(s,name){const ix=orientIndices(s.length,name),a=Array(s.length);for(let j=0;j<ix.length;j++)a[ix[j]]=s[j];return a.join('');}
function tokens(s){const a=[s.slice(0,2)];for(let i=2;i<s.length;i+=5)a.push(s.slice(i,i+5));return a;}
function brute4(mat){let best=-1,w=[];function r(i,m,u){if(i===4){const z=m.reduce((s,v,j)=>s+mat[j][v],0);if(z>best){best=z;w=[m.slice()];}else if(z===best)w.push(m.slice());return;}for(let v=0;v<4;v++)if(!u.has(v)){m.push(v);u.add(v);r(i+1,m,u);u.delete(v);m.pop();}}r(0,[],new Set());return {upper:best,witnesses:w};}
function pyRefs(req){const z=cp.spawnSync('python3',[path.join(HERE,'ofb8_pyref.py')],{input:JSON.stringify(req),encoding:'utf8'});assert(z.status===0,'pyref '+z.stderr);return new Map(JSON.parse(z.stdout).map(x=>[x.id,Buffer.from(x.keystream_hex,'hex')]));}
async function compute(){verifyPins();const ctx=await X.load(),n=546,zero=Buffer.alloc(n),probe=Buffer.from(Array.from({length:n},(_,i)=>crypto.createHash('sha256').update('ASTRA extension probe|'+i).digest()[i%32])),aRows=[];
 for(const c of X.baseA()){const k=X.decrypt(ctx,c.cipher,c.key,c.iv,zero,c.mode),d=X.decrypt(ctx,c.cipher,c.key,c.iv,probe,c.mode),want=X.xor(probe,k);let enc=null;if(c.kind==='block')enc=X.encrypt(ctx,c.cipher,c.key,c.iv,probe,c.mode).equals(want);const ok=d.equals(want)&&(enc===null||enc);assert(ok,'A law '+JSON.stringify(c));aRows.push({...c,eligible:ok,keystream_sha256:sha(k),probe_output_sha256:sha(d),first_mismatch:mismatch(d,want),encrypt_equals_decrypt:enc});}
 assert(aRows.length===312,'A rows');
 const bRows=[];for(const c of X.baseB()){const k=X.ofb8Keystream(ctx,c.cipher,c.key,c.iv,64);bRows.push({...c,length:64,keystream_hex:k.toString('hex'),keystream_sha256:sha(k),first_ecb_byte:k[0]});}assert(bRows.length===228,'B rows');
 const req=[];for(const cipher of ['rijndael-128','des','blowfish'])for(const key of X.KEYS)for(const iv of ['zero','ascii0'])req.push({id:[cipher,key,iv].join('|'),cipher,key,iv_hex:X.ivBytes(X.R.CIPHER_INFO[cipher].blockSize,iv).toString('hex'),length:256});const refs=pyRefs(req),pyRows=[];for(const q of req){const got=X.ofb8Keystream(ctx,q.cipher,q.key,q.iv_hex.match(/^00/) ? 'zero':'ascii0',256),want=refs.get(q.id);assert(got.equals(want),'pyref '+q.id);pyRows.push({id:q.id,keystream_sha256:sha(got),bytes:256,exact:true});}
 const old=JSON.parse(fs.readFileSync(OLD_OFB8)),oldRows=[];for(const r of old.rows.filter(x=>x.fixture==='all_256_bytes')){const cm={aes128:'rijndael-128',blowfish:'blowfish',des:'des'}[r.cipher],iv=r.iv_kind==='nul'?'zero':'ascii0',ks=X.ofb8Keystream(ctx,cm,'Zombies',iv,256),pt=Buffer.from(r.plaintext_hex,'hex'),ct=X.xor(pt,ks);assert(ct.toString('hex')===r.ciphertext_hex,'historical C '+r.cipher+' '+iv);oldRows.push({cipher:r.cipher,iv,actual_c_ciphertext_sha256:r.ciphertext_sha256,wasm_recurrence_ciphertext_sha256:sha(ct),exact:true,zero_stream:ks.every(x=>x===0)});}assert(oldRows.length===6,'old rows');
 const map=[7,2,13,0,11,5,15,8,1,12,4,14,6,10,3,9],phrase=Buffer.from('THE SHUFFLED HEX MAP REMAINS EXACT UNDER THE FIXED KEYSTREAM. 0123456789!? ','ascii'),plain=Buffer.alloc(n);for(let i=0;i<n;i++)plain[i]=phrase[i%phrase.length];const plantContexts=[X.baseA().find(x=>x.cipher==='des'&&x.mode==='ctr'&&x.key==='ZOMBIE'&&x.iv==='ascii0'),X.baseA().find(x=>x.cipher==='panama'&&x.key==='zombies'),X.baseA().find(x=>x.cipher==='arcfour'&&x.key==='Zombie'),X.baseB().find(x=>x.cipher==='rijndael-128'&&x.key==='zombie'&&x.iv==='ascii0'),X.baseB().find(x=>x.cipher==='des'&&x.key==='ZOMBIE'&&x.iv==='zero'),X.baseB().find(x=>x.cipher==='blowfish'&&x.key==='Zombies'&&x.iv==='zero')],plants=[];
 for(const c of plantContexts){const ks=c.family==='ofb8'?X.ofb8Keystream(ctx,c.cipher,c.key,c.iv,n):X.decrypt(ctx,c.cipher,c.key,c.iv,zero,c.mode),ct=X.xor(plain,ks),seen=M.displayEncode(ct,map);for(const o of O.ORIENTATIONS){const canonical=inverseOrient(seen,o),display=O.orientations(canonical,tokens(canonical))[o];assert(display===seen,'orient plant');const z=M.analyze(display,ks);assert(z.combined_upper===n&&z.solver.status==='sat'&&z.plaintext&&[...z.plaintext].every(v=>M.ALLOWED.has(v)),'plant solve');const mapped=M.applyMap(display,z.solver.mapping);assert(X.xor(mapped,ks).equals(z.plaintext)&&X.xor(z.plaintext,ks).equals(mapped),'plant inverse');plants.push({id:[c.family,c.cipher,c.mode,c.key,c.iv,o].join('|'),family:c.family,cipher:c.cipher,mode:c.mode,key:c.key,iv:c.iv,orientation:o,keystream_sha256:sha(ks),zero_keystream:ks.every(x=>x===0),truth_mapping:map,truth_exact:M.applyMap(display,map).equals(ct),high_upper:z.high_bound.upper,assignment_upper:z.assignment_bound.upper,pair_upper:z.pair_bound.upper,solver_status:z.solver.status,solver_nodes:z.solver.nodes,recovered_mapping:z.solver.mapping,recovered_plaintext_sha256:sha(z.plaintext),decrypt_reencrypt_exact:true});}}assert(plants.length===30&&plants.some(x=>x.zero_keystream),'plants');
 const wrong=[];for(const c of plantContexts){const ks=c.family==='ofb8'?X.ofb8Keystream(ctx,c.cipher,c.key,c.iv,n):X.decrypt(ctx,c.cipher,c.key,c.iv,zero,c.mode),wrongKey=c.key==='Zombie'?'zombie':'Zombie',wk=c.family==='ofb8'?X.ofb8Keystream(ctx,c.cipher,wrongKey,c.iv,n):X.decrypt(ctx,c.cipher,wrongKey,c.iv,zero,c.mode),ct=X.xor(plain,ks),display=M.displayEncode(ct,map),z=M.analyze(display,wk);assert(z.combined_upper<n,'wrong full');wrong.push({id:[c.family,c.cipher,c.mode,c.key,'wrong='+wrongKey,c.iv].join('|'),high_upper:z.high_bound.upper,assignment_upper:z.assignment_bound?z.assignment_bound.upper:null,combined_upper:z.combined_upper,threshold_75:z.threshold_75,certified_below_75:z.certified_below_75,full_ascii_excluded:z.combined_upper<n});}
 const small=[];for(let f=0;f<8;f++){const h=crypto.createHash('sha256').update('ASTRA assignment '+f).digest(),m=Array.from({length:16},()=>Array(16).fill(0));for(let i=4;i<16;i++)m[i][i]=1000;const m4=Array.from({length:4},(_,i)=>Array.from({length:4},(_,j)=>h[i*4+j]%23));for(let i=0;i<4;i++)for(let j=0;j<4;j++)m[i][j]=m4[i][j];const b=brute4(m4),z=M.assignmentUpperFromMatrix(m);assert(z.upper===12000+b.upper&&z.mapping.slice(4).every((v,i)=>v===i+4),'assignment exact');assert(b.witnesses.some(w=>JSON.stringify(w)===JSON.stringify(z.mapping.slice(0,4))),'assignment witness');small.push({fixture:f,matrix4:m4,brute_upper:b.upper,brute_witness_count:b.witnesses.length,dp_upper:z.upper,dp_mapping:z.mapping});}
 return {identity:'ASTRA',status:'synthetic controls complete',target_evaluated:false,rev7_read:false,scope:{family_A:{description:'additional literal keys for full OFB, CTR, Panama, Arcfour',base_contexts:312,target_cells:1560,keys:X.EXTRA_KEYS},family_B:{description:'historical 8-bit OFB recurrence over actual ECB primitives',base_contexts:228,target_cells:1140,keys:X.KEYS},orientations:O.ORIENTATIONS,total_incremental_base_contexts:540,total_target_cells:2700},model:{endpoint:'TAB LF CR and ASCII 32..126',threshold:'ceil(0.75*N)',row_max_bound:'independent high-nibble row maxima',assignment_bound:'exact maximum-weight bijection over the 16x16 high-nibble matrix, computed only when row-max is weak',pair_bound:'ordered-pair-class relaxation after weak assignment bound',full_ascii_solver:'exact only for 100 percent ASCII; never used to claim 75 percent exclusion'},source_pins:{...PINS,'model.js':fsha(path.join(HERE,'model.js')),'runtime.js':fsha(path.join(HERE,'runtime.js')),'controls.js':fsha(__filename)},family_A_xor_law:{messages:2,rows:aRows,eligible:aRows.length},family_B_recurrence:{rows:bRows,source_semantics:'ECB-encrypt register; emit byte zero; shift left one byte; append emitted byte'},pycryptodome_ofb8_controls:pyRows,historical_compiled_c_ofb8_controls:oldRows,plants,wrong_key_controls:wrong,assignment_exact_small_controls:small,assertions:{counts_1560_plus_1140_equal_2700:true,all_additional_full_mode_laws:true,all_three_cipher_pyrefs_exact:true,all_six_historical_c_rows_exact:true,zero_keystream_plant_present:true,all_30_plants_solve_and_reencrypt:true,all_assignment_DP_controls_equal_exhaustive:true},limits:['No Rev7 bytes are read or evaluated.','Panama and Arcfour fixed-keystream status remains empirical because their underlying C sources are absent from the captured package.','A bound at or above 75 percent is unresolved unless a sound stronger weighted bound decides it. Full-ASCII CSP UNSAT alone does not exclude 75-percent ASCII.']};}
async function main(){let out=null;if(process.argv.length===4&&process.argv[2]==='--generate')out=path.resolve(process.argv[3]);else if(process.argv.length!==2)throw Error('usage: node controls.js [--generate NEW_PATH]');const got=await compute();if(out){assert(!fs.existsSync(out),'refuse existing');fs.writeFileSync(out,stable(got));console.log(JSON.stringify({identity:'ASTRA',written:out,sha256:fsha(out),cells:got.scope.total_target_cells,plants:got.plants.length}));}else{assert(fs.existsSync(OUTPUT),'controls ledger absent');assert(stable(JSON.parse(fs.readFileSync(OUTPUT)))===stable(got),'controls mismatch');console.log(JSON.stringify({identity:'ASTRA',status:'PASS',ledger_sha256:fsha(OUTPUT),cells:got.scope.total_target_cells,plants:got.plants.length}));}}
main().catch(e=>{console.error(e.stack||String(e));process.exitCode=1;});
